import Foundation

/// Generates an inline HTML5 video player page for HLS streams (.m3u8),
/// preventing iOS WebKit from taking over with a full-screen native AVPlayer
/// document presentation when a user navigates directly to a manifest URL.
public enum BrowserHLSInlinePlayer: Sendable {

    /// Identifying marker embedded in generated HTML.
    public static let identifierMarker = "data-lid-inline-hls-player"

    /// Determines if an HTML string was generated by `BrowserHLSInlinePlayer`.
    public static func isInlinePlayerHTML(_ html: String) -> Bool {
        html.contains(identifierMarker) || html.contains("id=\"hls-player\"")
    }

    /// Generates self-contained HTML for playing the given HLS stream URL inline in a browser tab.
    public static func html(for streamURL: URL, title: String? = nil) -> String {
        let rawTitle: String
        if let title = title?.trimmingCharacters(in: .whitespacesAndNewlines), !title.isEmpty {
            rawTitle = title
        } else {
            let lastComponent = streamURL.lastPathComponent.trimmingCharacters(in: .whitespacesAndNewlines)
            rawTitle = lastComponent.isEmpty ? (streamURL.host ?? "HLS Stream") : lastComponent
        }

        let escapedTitle = escapeHTML(rawTitle)
        let host = streamURL.host ?? "Live / On-Demand Stream"
        let escapedHost = escapeHTML(host)
        let escapedURL = escapeHTML(streamURL.absoluteString)
        let ext = streamURL.pathExtension.lowercased()
        let isHLS = ext == "m3u8" || streamURL.absoluteString.lowercased().contains(".m3u8")
        let isAudio = ["mp3", "m4a", "aac", "wav", "flac", "ogg", "opus"].contains(ext)
        let isVideo = ["mp4", "m4v", "mov", "webm", "mkv", "avi"].contains(ext)
        let badgeText = isHLS ? "HLS Stream" : (isAudio ? "Audio Stream" : (isVideo ? "Video Stream" : "Media Stream"))

        return """
        <!DOCTYPE html>
        <html lang="en" \(identifierMarker)="true">
        <head>
            <meta charset="utf-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
            <title>\(escapedTitle)</title>
            <style>
                * {
                    box-sizing: border-box;
                    margin: 0;
                    padding: 0;
                }
                body {
                    background-color: #0b0f19;
                    color: #f3f4f6;
                    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
                    min-height: 100vh;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: center;
                    padding: 16px;
                    -webkit-font-smoothing: antialiased;
                }
                .container {
                    width: 100%;
                    max-width: 860px;
                    display: flex;
                    flex-direction: column;
                    gap: 16px;
                }
                .header {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    flex-wrap: wrap;
                    gap: 8px;
                    padding: 0 4px;
                }
                .title-group {
                    display: flex;
                    flex-direction: column;
                    gap: 4px;
                    overflow: hidden;
                }
                .stream-title {
                    font-size: 1.15rem;
                    font-weight: 600;
                    color: #ffffff;
                    text-overflow: ellipsis;
                    overflow: hidden;
                    white-space: nowrap;
                }
                .stream-host {
                    font-size: 0.85rem;
                    color: #9ca3af;
                }
                .badge {
                    display: inline-flex;
                    align-items: center;
                    padding: 4px 10px;
                    font-size: 0.75rem;
                    font-weight: 700;
                    letter-spacing: 0.05em;
                    text-transform: uppercase;
                    border-radius: 9999px;
                    background-color: rgba(59, 130, 246, 0.2);
                    color: #60a5fa;
                    border: 1px solid rgba(59, 130, 246, 0.4);
                }
                .video-wrapper {
                    position: relative;
                    width: 100%;
                    background-color: #000000;
                    border-radius: 12px;
                    overflow: hidden;
                    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 10px 10px -5px rgba(0, 0, 0, 0.4);
                    border: 1px solid #1f2937;
                }
                video {
                    width: 100%;
                    max-height: 70vh;
                    display: block;
                    background-color: #000000;
                    object-fit: contain;
                }
                .error-banner {
                    display: none;
                    background-color: rgba(239, 68, 68, 0.15);
                    border: 1px solid rgba(239, 68, 68, 0.4);
                    border-radius: 8px;
                    padding: 12px 16px;
                    margin-top: 8px;
                }
                .error-header {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    gap: 8px;
                }
                .error-title {
                    font-weight: 600;
                    color: #fca5a5;
                    font-size: 0.95rem;
                }
                .error-detail {
                    color: #f87171;
                    font-size: 0.85rem;
                    margin-top: 4px;
                }
                .retry-btn {
                    background-color: #ef4444;
                    color: #ffffff;
                    border: none;
                    padding: 6px 14px;
                    font-size: 0.85rem;
                    font-weight: 600;
                    border-radius: 6px;
                    cursor: pointer;
                    transition: background-color 0.2s;
                }
                .retry-btn:active {
                    background-color: #dc2626;
                }
                .footer {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    gap: 6px;
                    font-size: 0.8rem;
                    color: #6b7280;
                    text-align: center;
                    padding: 4px 8px;
                }
            </style>
        </head>
        <body>
            <div class="container">
                <div class="header">
                    <div class="title-group">
                        <div class="stream-title">\(escapedTitle)</div>
                        <div class="stream-host">\(escapedHost)</div>
                    </div>
                    <span class="badge">\(badgeText)</span>
                </div>

                <div class="video-wrapper">
                    <video id="hls-player" controls playsinline webkit-playsinline preload="auto">
                        <source src="\(escapedURL)" type="application/vnd.apple.mpegurl">
                        <source src="\(escapedURL)" type="application/x-mpegurl">
                        <source src="\(escapedURL)" type="video/mp4">
                        <source src="\(escapedURL)" type="video/quicktime">
                        <source src="\(escapedURL)" type="video/webm">
                        <source src="\(escapedURL)" type="audio/mpeg">
                        <source src="\(escapedURL)" type="audio/mp4">
                        <source src="\(escapedURL)">
                        Your browser does not support inline media playback.
                    </video>
                </div>

                <div id="error-banner" class="error-banner">
                    <div class="error-header">
                        <span class="error-title">Playback Incomplete</span>
                        <button type="button" class="retry-btn" onclick="retryPlayback()">Retry Playback</button>
                    </div>
                    <div id="error-detail" class="error-detail">Stream encountered a playback error or network timeout.</div>
                </div>

                <div class="footer">
                    <span>Playing inline in tab &bull; Tap Download in toolbar to save specific resolutions.</span>
                </div>
            </div>

            <script>
                (function() {
                    const player = document.getElementById('hls-player');
                    const errorBanner = document.getElementById('error-banner');
                    const errorDetail = document.getElementById('error-detail');

                    if (player) {
                        player.playsInline = true;
                        player.setAttribute('playsinline', '');
                        player.setAttribute('webkit-playsinline', '');

                        player.addEventListener('error', function() {
                            if (errorBanner) {
                                errorBanner.style.display = 'block';
                            }
                            if (errorDetail && player.error) {
                                const codeMsg = {
                                    1: 'Playback aborted by user',
                                    2: 'Network error encountered during playback',
                                    3: 'Media decoding error',
                                    4: 'Media stream format not supported or unavailable'
                                };
                                const msg = codeMsg[player.error.code] || player.error.message || 'Stream playback failed';
                                errorDetail.textContent = 'Error code ' + player.error.code + ': ' + msg;
                            }
                        });

                        player.addEventListener('playing', function() {
                            if (errorBanner) {
                                errorBanner.style.display = 'none';
                            }
                        });
                    }

                    window.retryPlayback = function() {
                        if (errorBanner) {
                            errorBanner.style.display = 'none';
                        }
                        if (player) {
                            player.load();
                            player.play().catch(function(err) {
                                console.warn('Autoplay prevented or load failed:', err);
                            });
                        }
                    };
                })();
            </script>
        </body>
        </html>
        """
    }

    private static func escapeHTML(_ string: String) -> String {
        string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#39;")
    }
}

